# Let's enumerate all possible magic sequences of length 3
# A magic sequence x[0], x[1], x[2] where x[i] = count of i in the sequence

def check_magic(seq):
    n = len(seq)
    for i in range(n):
        if seq[i] != seq.count(i):
            return False
    return True

# Generate all sequences where sum = 3 (since sum of counts must equal length)
solutions = []
for a in range(4):
    for b in range(4):
        for c in range(4):
            seq = [a, b, c]
            if sum(seq) == 3 and check_magic(seq):
                solutions.append(seq)

print("Solutions:", solutions)

# Also check without the sum constraint (though it should be implied)
all_solutions = []
for a in range(4):
    for b in range(4):
        for c in range(4):
            seq = [a, b, c]
            if check_magic(seq):
                all_solutions.append(seq)

print("All solutions (without sum constraint):", all_solutions)

# Let's verify more thoroughly - maybe values could be larger than 3
# Though logically, x[i] can't exceed 3 (the length of the sequence)

def check_magic(seq):
    n = len(seq)
    for i in range(n):
        if seq[i] != seq.count(i):
            return False
    return True

# Check all possible sequences of length 3 with values 0-3
solutions = []
for a in range(4):
    for b in range(4):
        for c in range(4):
            seq = [a, b, c]
            if check_magic(seq):
                solutions.append(seq)

print("Solutions:", solutions)

# Also verify known magic sequences for other lengths
for n in range(1, 10):
    sols = []
    # For efficiency, only check sequences where sum = n
    def generate(idx, current, remaining_sum):
        if idx == n:
            if remaining_sum == 0 and check_magic(current):
                sols.append(current[:])
            return
        for val in range(min(remaining_sum + 1, n + 1)):
            current.append(val)
            generate(idx + 1, current, remaining_sum - val)
            current.pop()

    generate(0, [], n)
    print(f"n={n}: {sols}")
